import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data

assets = ['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
end_w = {'NDX':9.52,'US10Y':8.74,'SX5E':8.46,'WTI':8.04,'000688.SH':7.90,'HSI':7.75,'SOX':6.61,'ETH':6.60,'CN10Y':6.17,'BTC':5.95,'000300.SH':5.95,'COPPER':5.60,'XAU':5.47,'N225':4.00,'SPX':3.21}
end_w = {k: v/100.0 for k,v in end_w.items()}

rets = {}
for a in assets:
    df = get_stock_daily_data(symbol=a, days=30)
    df = df.copy(); df['date'] = pd.to_datetime(df['date']); df = df.set_index('date').sort_index()
    c = df['close']
    # find 1011 close and 1025 close
    sub = df.loc['2030-10-11':'2030-10-25']
    if len(sub) >= 2:
        r = sub['close'].iloc[-1]/sub['close'].iloc[0] - 1
        rets[a] = r
    else:
        rets[a] = None
        print(a, 'no data')

print('--- block returns 1011->1025 ---')
for a in assets:
    print(f"{a:10s} {rets[a]*100:7.2f}%")

# estimate executed weights at 1011: w_exec = w_end/(1+r), then normalize
w_exec = {}
for a in assets:
    if rets[a] is not None:
        w_exec[a] = end_w[a]/(1+rets[a])
s = sum(w_exec.values())
w_exec = {k: v/s for k,v in w_exec.items()}
print('--- estimated executed weights @1011 ---')
for a in sorted(w_exec, key=lambda x: -w_exec[x]):
    print(f"{a:10s} {w_exec[a]*100:5.2f}%")
print('sum', round(sum(w_exec.values()),4), 'BTC+ETH', round((w_exec.get('BTC',0)+w_exec.get('ETH',0))*100,2), 'WTI+COPPER', round((w_exec.get('WTI',0)+w_exec.get('COPPER',0))*100,2))

# attribution
contrib = {a: w_exec[a]*rets[a] for a in assets if rets[a] is not None}
tot = sum(contrib.values())
print('--- attribution (pp) ---')
for a in sorted(contrib, key=lambda x: -contrib[x]):
    print(f"{a:10s} w={w_exec[a]*100:5.2f}% r={rets[a]*100:7.2f}% contrib={contrib[a]*100:6.2f}pp")
print('total block contrib:', round(tot*100,2), '%')
